-- Encyclopedia tables and initial seed data

CREATE TABLE IF NOT EXISTS encyclopedia_categories (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    icon VARCHAR(16),
    archetype VARCHAR(64),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS encyclopedia_articles (
    id VARCHAR(128) PRIMARY KEY,
    category_id VARCHAR(64) NOT NULL REFERENCES encyclopedia_categories(id),
    article_type VARCHAR(32) NOT NULL,
    title VARCHAR(255) NOT NULL,
    summary TEXT NOT NULL,
    content TEXT NOT NULL,
    wikipedia_url VARCHAR(512),
    location_region VARCHAR(255),
    location_country VARCHAR(255),
    location_latitude DOUBLE PRECISION,
    location_longitude DOUBLE PRECISION,
    ingredient_kind VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS encyclopedia_article_translations (
    article_id VARCHAR(128) NOT NULL REFERENCES encyclopedia_articles(id) ON DELETE CASCADE,
    language_code VARCHAR(16) NOT NULL,
    title VARCHAR(255),
    summary TEXT,
    content TEXT NOT NULL,
    wikipedia_url VARCHAR(512),
    PRIMARY KEY (article_id, language_code)
);

CREATE TABLE IF NOT EXISTS encyclopedia_article_tags (
    article_id VARCHAR(128) NOT NULL REFERENCES encyclopedia_articles(id) ON DELETE CASCADE,
    tag VARCHAR(128) NOT NULL,
    PRIMARY KEY (article_id, tag)
);

CREATE TABLE IF NOT EXISTS encyclopedia_article_related (
    article_id VARCHAR(128) NOT NULL REFERENCES encyclopedia_articles(id) ON DELETE CASCADE,
    related_article_id VARCHAR(128) NOT NULL,
    PRIMARY KEY (article_id, related_article_id)
);

CREATE TABLE IF NOT EXISTS encyclopedia_article_ingredient_aliases (
    article_id VARCHAR(128) NOT NULL REFERENCES encyclopedia_articles(id) ON DELETE CASCADE,
    alias VARCHAR(255) NOT NULL,
    PRIMARY KEY (article_id, alias)
);

CREATE INDEX idx_articles_updated_at ON encyclopedia_articles(updated_at);
CREATE INDEX idx_articles_category ON encyclopedia_articles(category_id);

