INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('wine-red-basics', 'wine', 'general', 'Red Wine: Craft & Fundamentals', 'An introduction to red wine fermentation, skin contact, tannin structure, and aging potential.', 'Red wine is crafted by fermenting crushed dark grapes with their skins, seeds, and stems. This extended maceration imparts deep anthocyanin pigmentation and structured tannins. Renowned regions such as [[wine-burgundy|Burgundy]] and [[wine-bordeaux|Bordeaux]] demonstrate how terroir shapes the expression of grape varieties like [[wine-pinot-noir|Pinot Noir]] and [[wine-cabernet-sauvignon|Cabernet Sauvignon]]. Serving red wine at 16–18°C in wide-bowled glassware allows volatile aroma compounds to aerate and bloom.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('wine-burgundy', 'wine', 'location', 'Burgundy (Bourgogne)', 'The historic French heartland of limestone terroir, single-varietal elegance, and climat classification.', 'Burgundy, situated in eastern France, represents the apex of terroir-driven winemaking. Centered on the limestone-rich slopes of [[wine-burgundy|the Côte d''Or]], the region produces benchmark expressions of [[wine-pinot-noir]] and Chardonnay. Vineyards are meticulously classified into Grand Cru, Premier Cru, and Village appellations, tracing back to Cistercian monastic viticulture.', 'https://en.wikipedia.org/wiki/Burgundy_wine', 'Burgundy (Côte d''Or)', 'France', NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('wine-pinot-noir', 'wine', 'ingredient', 'Pinot Noir', 'A thin-skinned, notoriously finicky red grape variety celebrated for red fruit aromatics and earthy complexity.', 'Pinot Noir is one of the most ancient cultivated grape varieties. Characterized by thin skins and tight bunches, it is highly sensitive to climate and soil composition. In [[wine-burgundy|Burgundy]], it produces ethereal aromas of red cherry, forest floor, and wild mushrooms. It is also a core grape in sparkling wine production alongside Chardonnay and Pinot Meunier.', 'https://en.wikipedia.org/wiki/Pinot_noir', NULL, NULL, NULL, NULL, 'Vitis vinifera grape');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('wine-bordeaux', 'wine', 'location', 'Bordeaux', 'World-famous maritime wine region celebrated for structured Left Bank and Right Bank red blends.', 'Located along the Gironde Estuary in southwest France, Bordeaux is renowned for its gravelly and clay-limestone soils. The Left Bank highlights [[wine-cabernet-sauvignon]], while the Right Bank favors Merlot. Bordeaux blends typically undergo aging in [[spirits-oak-aging|oak barrels]] to soften firm tannins and add cedar-vanilla spice.', 'https://en.wikipedia.org/wiki/Bordeaux_wine', 'Bordeaux', 'France', NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('wine-cabernet-sauvignon', 'wine', 'ingredient', 'Cabernet Sauvignon', 'A resilient, thick-skinned grape known for intense blackcurrant, cedar, and high tannin profile.', 'Born from a spontaneous cross between Cabernet Franc and Sauvignon Blanc, Cabernet Sauvignon thrives in gravelly soils like those of [[wine-bordeaux|Bordeaux]]. Its thick skins provide rich color and high tannins, allowing wines to age gracefully for decades in [[spirits-oak-aging|oak barrels]].', 'https://en.wikipedia.org/wiki/Cabernet_Sauvignon', NULL, NULL, NULL, NULL, 'Vitis vinifera grape');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('beer-craft-fundamentals', 'beer', 'general', 'Beer: Brewing & Hop Chemistry', 'How water, malted barley, yeast, and hops combine to create the world''s most diverse fermented beverage.', 'Beer brewing is an intricate science of starch conversion and fermentation. Mashing converts barley starches into sweet wort, which is boiled with [[beer-hops|hops]] for bitterness and aromatic essential oils. Regional water mineral profiles, such as the soft waters of [[beer-plzen|Plzeň]] or sulfate-rich wells of Burton-on-Trent, dictate classic beer styles from crisp lagers to resinous IPAs.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('beer-plzen', 'beer', 'location', 'Plzeň (Pilsen)', 'The Bohemian birthplace of the golden pilsner lager and bottom-fermentation revolution.', 'In 1842, Bavarian brewer Josef Groll utilized Plzeň''s exceptionally soft Bohemian water, pale malted [[beer-barley|barley]], and fragrant Saaz [[beer-hops|noble hops]] to brew the world''s first clear golden pilsner. This breakthrough transformed global brewing away from dark cloudy ales.', 'https://en.wikipedia.org/wiki/Pilsner', 'Bohemia', 'Czech Republic', NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('beer-hops', 'beer', 'ingredient', 'Hops (Humulus lupulus)', 'The cone-shaped flowers of the hop vine that provide bitterness, preservation, and essential oils.', 'Hops contain alpha acids that isomerize during the boil to impart balancing bitterness, as well as beta acids and myrcene/humulene oils that deliver citrus, pine, and floral aromas. Historic brewing in [[beer-plzen|Plzeň]] relied on Saaz hops, whereas modern craft brewing uses dry-hopping to maximize tropical fruit aromas.', 'https://en.wikipedia.org/wiki/Hops', NULL, NULL, NULL, NULL, 'Botanical cone (Cannabaceae)');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('beer-barley', 'beer', 'ingredient', 'Malted Barley', 'The backbone grain of brewing, kilned to produce fermentable sugars, color, and malty flavor.', 'Barley is steeped and germinated during malting to activate amylase enzymes before being kilned. Light kilning yields crisp pilsner malts used in [[beer-plzen|Plzeň]], while heavy roasting produces chocolate and coffee notes in stouts and porters.', 'https://en.wikipedia.org/wiki/Barley', NULL, NULL, NULL, NULL, 'Cereal grain (Hordeum vulgare)');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('coffee-specialty-origins', 'coffee', 'general', 'Specialty Coffee: Terroir & Processing', 'Understanding how elevation, Arabica genetics, and washed vs. natural processing define cup quality.', 'Specialty coffee focuses on high-altitude [[coffee-arabica|Coffea arabica]] varieties cultivated in equatorial volcanic terroirs. The birthland of coffee, [[coffee-yirgacheffe|Yirgacheffe in Ethiopia]], produces renowned jasmine and bergamot floral notes. Post-harvest processing—whether washed for clean acidity or natural for jammy fruitiness—dramatically influences sweetness and body.', 'https://en.wikipedia.org/wiki/Specialty_coffee', NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('coffee-yirgacheffe', 'coffee', 'location', 'Yirgacheffe, Sidamo', 'High-altitude micro-region in southern Ethiopia famed for floral, citrus-driven washed coffees.', 'Perched between 1,700 and 2,200 meters in southern Ethiopia, Yirgacheffe''s fertile red soil and misty highlands cultivate heirloom [[coffee-arabica]] strains. Washed Yirgacheffe is universally celebrated for its delicate body, black tea finish, and vibrant lemon-blossom aromatics.', 'https://en.wikipedia.org/wiki/Yirgachefe', 'Gedeo Zone, SNNPR', 'Ethiopia', NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('coffee-arabica', 'coffee', 'ingredient', 'Coffea Arabica', 'The premium coffee plant species prized for complex acidity, aromatic sweetness, and delicate body.', 'Coffea arabica accounts for approximately 60% of global coffee production. Thriving at cooler high altitudes like [[coffee-yirgacheffe|Yirgacheffe]], Arabica beans contain twice the natural sugar content and less caffeine and chlorogenic acid than Robusta, resulting in refined berry, stone fruit, and chocolate notes.', 'https://en.wikipedia.org/wiki/Coffea_arabica', NULL, NULL, NULL, NULL, 'Botanical plant (Rubiaceae)');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('spirits-distillation-craft', 'spirits', 'general', 'Spirits: Distillation & Maturation', 'The transformation of fermented wash into high-proof spirits through pot stills, column stills, and barrel aging.', 'Distillation separates alcohol from water based on differing boiling points. In pot stills, copper contact removes sulfurous compounds, producing heavy, characterful spirits. The spirit is then aged in charred [[spirits-oak-aging|oak barrels]], where extraction, oxidation, and wood subtractive reactions impart vanilla, caramel, and smoky complexity, as seen in [[spirits-islay|Islay Single Malts]].', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('spirits-islay', 'spirits', 'location', 'Islay, Hebrides', 'The windswept Scottish island legendary for maritime, intensely peated single malt whiskies.', 'Islay is an island off the west coast of Scotland where malted barley is dried over smoldering peat fires. This infuses the malt with medicinal phenols, brine, and bonfire smoke. Matured in coastal warehouses in [[spirits-oak-aging|oak barrels]], Islay malts capture the salty sea spray of the Atlantic Ocean.', 'https://en.wikipedia.org/wiki/Islay_whisky', 'Inner Hebrides, Argyll', 'Scotland', NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('spirits-oak-aging', 'spirits', 'ingredient', 'Oak Casks & Wood Chemistry', 'American and French oak barrels providing lignin vanillins, lactones, and color to aged beverages.', 'Oak casks act as permeable maturation vessels for spirits and wines. Charring the interior activates wood sugars (caramelization) and creates an active charcoal layer that mellows harsh congeners. Oak imparts vanillin, coconut lactones, and wood tannins that structure spirits from [[spirits-islay|Islay whiskies]] to [[wine-bordeaux|Bordeaux wines]].', 'https://en.wikipedia.org/wiki/Oak_(wine)', NULL, NULL, NULL, NULL, 'Quercus alba & Quercus robur wood');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('tea-terroir-processing', 'tea', 'general', 'Tea: From Leaf to Infusion', 'How harvesting, withering, oxidation, and steaming shape white, green, oolong, and black teas.', 'All authentic teas originate from the leaves of [[tea-camellia|Camellia sinensis]]. The difference between green, oolong, and black tea lies in the degree of enzymatic oxidation. In [[tea-shizuoka|Shizuoka, Japan]], freshly picked leaves are quickly steamed to preserve chlorophyll and savory L-theanine amino acids.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('tea-shizuoka', 'tea', 'location', 'Shizuoka Prefecture', 'Japan''s premier tea capital beneath Mount Fuji, renowned for deep-steamed Fukamushi Sencha.', 'Shizuoka produces over 40% of Japan''s green tea. Blessed with volcanic soils, pure alpine meltwater, and coastal fog, tea masters cultivate [[tea-camellia|Camellia sinensis]] bushes that yield deep emerald, umami-rich green teas with a velvety sweet finish.', 'https://en.wikipedia.org/wiki/Shizuoka_Prefecture', 'Chūbu, Honshu', 'Japan', NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('tea-camellia', 'tea', 'ingredient', 'Camellia Sinensis', 'The evergreen tea plant rich in polyphenols, catechins, and relaxing L-theanine amino acids.', 'Camellia sinensis is an evergreen shrub native to East Asia. Varietal sinensis thrives in cool high terroirs like [[tea-shizuoka|Shizuoka]], producing delicate green teas, while varietal assamica yields robust, malty black teas. Catechins provide antioxidant bitterness, while L-theanine promotes calm mental clarity.', 'https://en.wikipedia.org/wiki/Camellia_sinensis', NULL, NULL, NULL, NULL, 'Evergreen shrub (Theaceae)');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('cocktail-mixology-principles', 'cocktail', 'general', 'Cocktails: The Art of Balance', 'Balancing strong, sweet, sour, bitter, and dilution in classic and modern craft cocktails.', 'Cocktail mixology is built on golden ratios harmonizing base spirits, citrus acids, sugar syrups, and aromatic modifiers like [[cocktail-aromatic-bitters|Aromatic Bitters]]. Shaking with ice introduces micro-bubbles and dilution for citrus sours, while stirring creates silky clarity for spirit-forward drinks aged in [[spirits-oak-aging|oak barrels]].', 'https://en.wikipedia.org/wiki/Cocktail', NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('cocktail-aromatic-bitters', 'cocktail', 'ingredient', 'Aromatic Bitters & Botanicals', 'Concentrated infusions of roots, bark, herbs, and spices that act as the spice rack of cocktails.', 'Bitters are high-proof alcoholic tinctures infused with gentian root, cinchona bark, clove, and cardamom. Even a few dashes bind discordant flavors together in cocktails such as the Old Fashioned and Manhattan, complementing base [[spirits-distillation-craft|distilled spirits]].', NULL, NULL, NULL, NULL, NULL, 'Botanical tincture');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('soda-effervescence-botanicals', 'soda-tonics', 'general', 'Tonics & Craft Sodas: Bubbles & Botanicals', 'The role of carbonation, natural cane sugars, and medicinal cinchona bark in refreshing mixers.', 'Modern premium mixers use natural carbonation and botanical infusions. High-quality tonic water derives its characteristic crisp bitterness from [[soda-quinine|Quinine]], historically harvested from the South American fever tree. Pairings with craft [[spirits-distillation-craft|spirits]] rely on fine perlage to carry aroma to the palate.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('soda-quinine', 'soda-tonics', 'ingredient', 'Quinine (Cinchona Bark)', 'The bitter crystalline alkaloid from the Cinchona tree that gives tonic water its signature snap.', 'Extracted from the bark of the Andean Cinchona tree, quinine was originally consumed by British colonial soldiers in India to prevent malaria. When blended with soda water and sugar, it gave birth to Indian Tonic Water. It provides a sharp, appetite-stimulating bitterness that balances botanical [[cocktail-mixology-principles|cocktails]].', 'https://en.wikipedia.org/wiki/Tonic_water', NULL, NULL, NULL, NULL, 'Alkaloid extract (Cinchona officinalis)');
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('other-wild-fermentations', 'other', 'general', 'Ancient Ferments: Mead, Cider & Kombucha', 'Wild honey ferments, tannic apple ciders, and SCOBY cultures that predate modern industrial brewing.', 'Beyond grain and grape, humanity has cultivated diverse wild ferments for millennia. Honey ferments into mead, while vintage apples in [[other-normandy|Normandy]] yield complex dry ciders. Probiotic cultures like kombucha rely on symbiotic yeasts and bacteria fermenting [[tea-camellia|Camellia sinensis]] tea.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('other-normandy', 'other', 'location', 'Normandy (Normandie)', 'The maritime orchard region of northern France celebrated for traditional Cidre Bouché and Calvados.', 'With over 700 heritage apple cultivars, Normandy''s temperate damp climate creates bittersweet, tannin-packed ciders. Natural fermentation and aging in [[spirits-oak-aging|oak barrels]] produce rustic, farmyard complexity and effervescent refreshment.', 'https://en.wikipedia.org/wiki/Cider', 'Normandy', 'France', NULL, NULL, NULL);
INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('wine-white-wine-acidity-and-texture', 'wine', 'general', 'White Wine: Acidity and Texture', 'An overview of the production choices, sensory characteristics, and serving context that define this subject.', 'White Wine: Acidity and Texture is best understood by examining ingredients, production technique, sensory balance, and serving conditions. An overview of the production choices, sensory characteristics, and serving context that define this subject. When tasting examples, assess aroma, sweetness, acidity or bitterness, body, texture, and finish; these traits vary with producer and style.', NULL, NULL, NULL, NULL, NULL, NULL);
