INSERT INTO encyclopedia_articles (id, category_id, article_type, title, summary, content, wikipedia_url, location_region, location_country, location_latitude, location_longitude, ingredient_kind) VALUES ('wine-champagne', 'wine', 'location', 'Champagne', 'A beverage region or cultural center shaped by local climate, raw materials, history, and production traditions.', 'Champagne has a distinctive place in beverage culture. A beverage region or cultural center shaped by local climate, raw materials, history, and production traditions. Geography and climate can influence available raw materials and production choices, while local history and expertise shape regional traditions. Individual producers differ, so regional descriptors should be treated as tendencies rather than guarantees.', NULL, 'Champagne', NULL, NULL, NULL, NULL);
