INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-red-basics', 'en', 'Red Wine: Craft & Fundamentals', 'An introduction to red wine fermentation, skin contact, tannin structure, and aging potential.', 'Red wine is crafted by fermenting crushed dark grapes with their skins, seeds, and stems. This extended maceration imparts deep anthocyanin pigmentation and structured tannins. Renowned regions such as [[wine-burgundy|Burgundy]] and [[wine-bordeaux|Bordeaux]] demonstrate how terroir shapes the expression of grape varieties like [[wine-pinot-noir|Pinot Noir]] and [[wine-cabernet-sauvignon|Cabernet Sauvignon]]. Serving red wine at 16–18°C in wide-bowled glassware allows volatile aroma compounds to aerate and bloom.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-red-basics', 'de', 'Rotwein: Handwerk & Grundlagen', 'Eine Einführung in die Maischegärung, Tanninstruktur, Extraktion und das Reifepotenzial von Rotwein.', 'Rotwein entsteht durch die Gärung von gequetschten dunklen Trauben mitsamt Schalen, Kernen und Stielen (Maische). Diese Mazeration sorgt für tiefe Anthocyan-Farbpigmente und strukturierte Gerbstoffe (Tannine). Berühmte Regionen wie das [[wine-burgundy|Burgund]] und [[wine-bordeaux|Bordeaux]] veranschaulichen, wie das Terroir Rebsorten wie [[wine-pinot-noir|Spätburgunder]] und [[wine-cabernet-sauvignon|Cabernet Sauvignon]] prägt. Serviert bei 16–18 °C in bauchigen Gläsern können sich die flüchtigen Aromen optimal entfalten.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-burgundy', 'en', 'Burgundy (Bourgogne)', 'The historic French heartland of limestone terroir, single-varietal elegance, and climat classification.', 'Burgundy, situated in eastern France, represents the apex of terroir-driven winemaking. Centered on the limestone-rich slopes of [[wine-burgundy|the Côte d''Or]], the region produces benchmark expressions of [[wine-pinot-noir]] and Chardonnay. Vineyards are meticulously classified into Grand Cru, Premier Cru, and Village appellations, tracing back to Cistercian monastic viticulture.', 'https://en.wikipedia.org/wiki/Burgundy_wine');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-burgundy', 'de', 'Burgund (Bourgogne)', 'Das historische französische Herzstück für kalkhaltiges Terroir, sortenreine Eleganz und Lagenklassifikation.', 'Das Burgund im Osten Frankreichs gilt als Inbegriff des terroirgeprägten Weinbaus. Entlang der kalksteinreichen Hänge der [[wine-burgundy|Côte d''Or]] entstehen weltberühmte Weine aus [[wine-pinot-noir|Spätburgunder]] und Chardonnay. Die Weinberge sind historisch bis auf die Zisterziensermönche zurückgehend akribisch in Grand Cru, Premier Cru und Village-Lagen (Climats) unterteilt.', 'https://de.wikipedia.org/wiki/Burgund_(Weinbaugebiet)');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-pinot-noir', 'en', 'Pinot Noir', 'A thin-skinned, notoriously finicky red grape variety celebrated for red fruit aromatics and earthy complexity.', 'Pinot Noir is one of the most ancient cultivated grape varieties. Characterized by thin skins and tight bunches, it is highly sensitive to climate and soil composition. In [[wine-burgundy|Burgundy]], it produces ethereal aromas of red cherry, forest floor, and wild mushrooms. It is also a core grape in sparkling wine production alongside Chardonnay and Pinot Meunier.', 'https://en.wikipedia.org/wiki/Pinot_noir');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-pinot-noir', 'de', 'Pinot Noir (Spätburgunder)', 'Eine dünnhäutige, anspruchsvolle Rotweinsorte, geschätzt für Aromen roter Früchte und erdige Komplexität.', 'Pinot Noir ist die Leitrebe des [[wine-burgundy|Burgunds]], wo sie einige der teuersten Weine der Welt hervorbringt. Charakterisiert durch dünne Schalen und dichte Trauben, reagiert sie hochsensibel auf Klima und Boden. Im [[wine-burgundy|Burgund]] entfaltet sie ätherische Aromen von Sauerkirsche, Waldboden und Pilzen. Zudem bildet sie neben Chardonnay und Pinot Meunier das Rückgrat der Champagner-Herstellung.', 'https://de.wikipedia.org/wiki/Sp%C3%A4tburgunder');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-bordeaux', 'en', 'Bordeaux', 'World-famous maritime wine region celebrated for structured Left Bank and Right Bank red blends.', 'Located along the Gironde Estuary in southwest France, Bordeaux is renowned for its gravelly and clay-limestone soils. The Left Bank highlights [[wine-cabernet-sauvignon]], while the Right Bank favors Merlot. Bordeaux blends typically undergo aging in [[spirits-oak-aging|oak barrels]] to soften firm tannins and add cedar-vanilla spice.', 'https://en.wikipedia.org/wiki/Bordeaux_wine');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-bordeaux', 'de', 'Bordeaux', 'Weltberühmte maritime Weinregion, bekannt für strukturierte Rotwein-Cuvées vom linken und rechten Ufer.', 'Entlang der Gironde-Mündung im Südwesten Frankreichs gelegen, ist Bordeaux berühmt für seine kiesigen und tonkalkhaltigen Böden. Das linke Ufer (Rive Gauche) betont [[wine-cabernet-sauvignon]], während das rechte Ufer (Rive Droite) von Merlot dominiert wird. Bordeaux-Cuvées reifen traditionell in [[spirits-oak-aging|Eichenfässern]], um Tannine abzurunden und Noten von Zeder und Vanille zu verleihen.', 'https://de.wikipedia.org/wiki/Bordeaux_(Weinbaugebiet)');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-cabernet-sauvignon', 'en', 'Cabernet Sauvignon', 'A resilient, thick-skinned grape known for intense blackcurrant, cedar, and high tannin profile.', 'Born from a spontaneous cross between Cabernet Franc and Sauvignon Blanc, Cabernet Sauvignon thrives in gravelly soils like those of [[wine-bordeaux|Bordeaux]]. Its thick skins provide rich color and high tannins, allowing wines to age gracefully for decades in [[spirits-oak-aging|oak barrels]].', 'https://en.wikipedia.org/wiki/Cabernet_Sauvignon');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-cabernet-sauvignon', 'de', 'Cabernet Sauvignon', 'Eine widerstandsfähige, dickhäutige Rebsorte, bekannt für Cassis-Aromen, Zedernholz und kräftige Tannine.', 'Hervorgegangen aus einer natürlichen Kreuzung von Cabernet Franc und Sauvignon Blanc, gedeiht Cabernet Sauvignon besonders gut auf Kiesböden wie im [[wine-bordeaux|Bordeaux]]. Die dicken Beerenhäute liefern tiefdunkle Farbe und prägnante Tannine, wodurch Weine nach Reifung in [[spirits-oak-aging|Eichenfässern]] über Jahrzehnte hinweg reifen können.', 'https://de.wikipedia.org/wiki/Cabernet_Sauvignon');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-craft-fundamentals', 'en', 'Beer: Brewing & Hop Chemistry', 'How water, malted barley, yeast, and hops combine to create the world''s most diverse fermented beverage.', 'Beer brewing is an intricate science of starch conversion and fermentation. Mashing converts barley starches into sweet wort, which is boiled with [[beer-hops|hops]] for bitterness and aromatic essential oils. Regional water mineral profiles, such as the soft waters of [[beer-plzen|Plzeň]] or sulfate-rich wells of Burton-on-Trent, dictate classic beer styles from crisp lagers to resinous IPAs.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-craft-fundamentals', 'de', 'Bier: Braukunst & Hopfenchemie', 'Wie Wasser, Gerstenmalz, Hefe und Hopfen das vielseitigste Gärgetränk der Welt erschaffen.', 'Das Bierbrauen ist ein faszinierendes Zusammenspiel aus Stärkeverzuckerung und Gärung. Beim Maischen wird Gerstenstärke in süße Würze umgewandelt, die anschließend mit [[beer-hops|Hopfen]] für Bittere und ätherische Aromen gekocht wird. Regionale Wasserprofile, wie das weiche Wasser aus [[beer-plzen|Pilsen]] oder sulfatreiche Quellen, prägen klassische Bierstile von schlanken Lagern bis zu hopfenbetonten IPAs.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-plzen', 'en', 'Plzeň (Pilsen)', 'The Bohemian birthplace of the golden pilsner lager and bottom-fermentation revolution.', 'In 1842, Bavarian brewer Josef Groll utilized Plzeň''s exceptionally soft Bohemian water, pale malted [[beer-barley|barley]], and fragrant Saaz [[beer-hops|noble hops]] to brew the world''s first clear golden pilsner. This breakthrough transformed global brewing away from dark cloudy ales.', 'https://en.wikipedia.org/wiki/Pilsner');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-plzen', 'de', 'Pilsen (Plzeň)', 'Die böhmische Wiege des goldenen Pilsner Lagers und der untergärigen Braurevolution.', 'Im Jahr 1842 nutzte der bayerische Braumeister Josef Groll das extrem weiche böhmische Wasser, helles [[beer-barley|Gerstenmalz]] und aromatischen Saazer [[beer-hops|Edelhopfen]], um das erste klare, goldene Pilsner der Welt zu brauen. Dieser Durchbruch revolutionierte die Brauwelt nachhaltig.', 'https://de.wikipedia.org/wiki/Pilsner_Bier');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-hops', 'en', 'Hops (Humulus lupulus)', 'The cone-shaped flowers of the hop vine that provide bitterness, preservation, and essential oils.', 'Hops contain alpha acids that isomerize during the boil to impart balancing bitterness, as well as beta acids and myrcene/humulene oils that deliver citrus, pine, and floral aromas. Historic brewing in [[beer-plzen|Plzeň]] relied on Saaz hops, whereas modern craft brewing uses dry-hopping to maximize tropical fruit aromas.', 'https://en.wikipedia.org/wiki/Hops');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-hops', 'de', 'Hopfen (Humulus lupulus)', 'Die zapfenförmigen Blüten der Hopfenpflanze, die für Bittere, Haltbarkeit und ätherische Öle sorgen.', 'Hopfen enthält Alphasäuren, die beim Würzekochen isomerisieren und dem Bier seine harmonische Bittere verleihen. Ätherische Öle wie Myrcen und Humulen steuern Citrus-, Kiefern- und Blütennoten bei. Während Traditionsbiere in [[beer-plzen|Pilsen]] auf Saazer Hopfen setzen, nutzt die moderne Craft-Bier-Szene das Kalthopfen (Dry-Hopping) für intensive Fruchtaromen.', 'https://de.wikipedia.org/wiki/Echter_Hopfen');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-barley', 'en', 'Malted Barley', 'The backbone grain of brewing, kilned to produce fermentable sugars, color, and malty flavor.', 'Barley is steeped and germinated during malting to activate amylase enzymes before being kilned. Light kilning yields crisp pilsner malts used in [[beer-plzen|Plzeň]], while heavy roasting produces chocolate and coffee notes in stouts and porters.', 'https://en.wikipedia.org/wiki/Barley');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('beer-barley', 'de', 'Gerstenmalz', 'Das Getreiderückgrat des Brauens, gedarrt zur Bildung vergärbarer Zucker, Farbe und Malzaromen.', 'Gerste wird beim Mälzen eingeweicht und zum Keimen gebracht, um Amylase-Enzyme zu aktivieren, bevor sie auf der Darre getrocknet wird. Helles Darren erzeugt klares Pilsner Malz wie in [[beer-plzen|Pilsen]], während starkes Rösten dunkle Schokoladen- und Kaffeenoten in Stouts und Portern hervorbringt.', 'https://de.wikipedia.org/wiki/Gerste');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('coffee-specialty-origins', 'en', 'Specialty Coffee: Terroir & Processing', 'Understanding how elevation, Arabica genetics, and washed vs. natural processing define cup quality.', 'Specialty coffee focuses on high-altitude [[coffee-arabica|Coffea arabica]] varieties cultivated in equatorial volcanic terroirs. The birthland of coffee, [[coffee-yirgacheffe|Yirgacheffe in Ethiopia]], produces renowned jasmine and bergamot floral notes. Post-harvest processing—whether washed for clean acidity or natural for jammy fruitiness—dramatically influences sweetness and body.', 'https://en.wikipedia.org/wiki/Specialty_coffee');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('coffee-specialty-origins', 'de', 'Spezialitätenkaffee: Terroir & Aufbereitung', 'Wie Höhenlage, Arabica-Genetik und nasse oder trockene Aufbereitung das Tassenprofil bestimmen.', 'Spezialitätenkaffee konzentriert sich auf hochgelegene [[coffee-arabica|Coffea Arabica]]-Varietäten aus äquatorialen Vulkanböden. Die Urheimat des Kaffees, [[coffee-yirgacheffe|Yirgacheffe in Äthiopien]], begeistert mit Noten von Jasmin und Bergamotte. Die Aufbereitung nach der Ernte – gewaschen (washed) für klare Säure oder trocken (natural) für beerige Süße – prägt das Aromenspektrum maßgeblich.', 'https://de.wikipedia.org/wiki/Spezialit%C3%A4tenkaffee');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('coffee-yirgacheffe', 'en', 'Yirgacheffe, Sidamo', 'High-altitude micro-region in southern Ethiopia famed for floral, citrus-driven washed coffees.', 'Perched between 1,700 and 2,200 meters in southern Ethiopia, Yirgacheffe''s fertile red soil and misty highlands cultivate heirloom [[coffee-arabica]] strains. Washed Yirgacheffe is universally celebrated for its delicate body, black tea finish, and vibrant lemon-blossom aromatics.', 'https://en.wikipedia.org/wiki/Yirgachefe');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('coffee-yirgacheffe', 'de', 'Yirgacheffe (Sidamo)', 'Hochland-Mikroregion in Südäthiopien, berühmt für florale, zitrusbetonte gewaschene Kaffees.', 'Gelegen auf 1.700 bis 2.200 Metern Höhe im Süden Äthiopiens, bieten die fruchtbaren roten Böden Yirgacheffes ideale Bedingungen für ursprüngliche [[coffee-arabica|Arabica-Landsorten]]. Gewaschener Yirgacheffe-Kaffee ist weltweit bekannt für seinen feinen Körper, Schwarzteenoten und lebhafte Aromen von Zitronenblüten.', 'https://de.wikipedia.org/wiki/Yirgacheffe_(Woreda)');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('coffee-arabica', 'en', 'Coffea Arabica', 'The premium coffee plant species prized for complex acidity, aromatic sweetness, and delicate body.', 'Coffea arabica accounts for approximately 60% of global coffee production. Thriving at cooler high altitudes like [[coffee-yirgacheffe|Yirgacheffe]], Arabica beans contain twice the natural sugar content and less caffeine and chlorogenic acid than Robusta, resulting in refined berry, stone fruit, and chocolate notes.', 'https://en.wikipedia.org/wiki/Coffea_arabica');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('coffee-arabica', 'de', 'Coffea Arabica', 'Die edle Kaffeepflanzenart, geschätzt für facettenreiche Säure, aromatische Süße und feinen Körper.', 'Coffea Arabica macht rund 60 % der weltweiten Kaffeeproduktion aus. Bevorzugt in kühleren Höhenlagen wie in [[coffee-yirgacheffe|Yirgacheffe]] wachsend, weisen Arabica-Bohnen doppelt so viel natürlichen Zucker und weniger Koffein als Robusta auf, was zu differenzierten Beeren-, Steinobst- und Kakaonoten führt.', 'https://de.wikipedia.org/wiki/Coffea_arabica');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('spirits-distillation-craft', 'en', 'Spirits: Distillation & Maturation', 'The transformation of fermented wash into high-proof spirits through pot stills, column stills, and barrel aging.', 'Distillation separates alcohol from water based on differing boiling points. In pot stills, copper contact removes sulfurous compounds, producing heavy, characterful spirits. The spirit is then aged in charred [[spirits-oak-aging|oak barrels]], where extraction, oxidation, and wood subtractive reactions impart vanilla, caramel, and smoky complexity, as seen in [[spirits-islay|Islay Single Malts]].', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('spirits-distillation-craft', 'de', 'Spirituosen: Destillation & Reifung', 'Die Veredelung vergorener Maischen zu hochprozentigen Destillaten durch Brennblasen und Fasslagerung.', 'Die Destillation trennt Alkohol und Wasser anhand ihrer unterschiedlichen Siedepunkte. In kupfernen Brennblasen (Pot Stills) bindet Kupfer unerwünschte Schwefelverbindungen und erzeugt aromatische Destillate. Durch anschließende Reifung in getoasteten [[spirits-oak-aging|Eichenfässern]] entstehen durch Extraktion und Oxidation Noten von Vanille, Karamell und Rauch, wie bei [[spirits-islay|Islay Single Malts]].', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('spirits-islay', 'en', 'Islay, Hebrides', 'The windswept Scottish island legendary for maritime, intensely peated single malt whiskies.', 'Islay is an island off the west coast of Scotland where malted barley is dried over smoldering peat fires. This infuses the malt with medicinal phenols, brine, and bonfire smoke. Matured in coastal warehouses in [[spirits-oak-aging|oak barrels]], Islay malts capture the salty sea spray of the Atlantic Ocean.', 'https://en.wikipedia.org/wiki/Islay_whisky');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('spirits-islay', 'de', 'Islay (Hebriden)', 'Die windgepeitschte schottische Insel, legendär für maritime, intensiv getorfte Single Malt Whiskys.', 'Islay ist eine Insel vor der Westküste Schottlands, auf der Gerstenmalz über schwelendem Torffeuer getrocknet wird. Dies verleiht dem Malz medizinische Phenole, Jod und Lagerfeuerrauch. Gereift in küstennahen Lagerhäusern in [[spirits-oak-aging|Eichenfässern]], fangen Islay-Whiskys die salzige Gischt des Atlantiks ein.', 'https://de.wikipedia.org/wiki/Islay_(Whiskyregion)');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('spirits-oak-aging', 'en', 'Oak Casks & Wood Chemistry', 'American and French oak barrels providing lignin vanillins, lactones, and color to aged beverages.', 'Oak casks act as permeable maturation vessels for spirits and wines. Charring the interior activates wood sugars (caramelization) and creates an active charcoal layer that mellows harsh congeners. Oak imparts vanillin, coconut lactones, and wood tannins that structure spirits from [[spirits-islay|Islay whiskies]] to [[wine-bordeaux|Bordeaux wines]].', 'https://en.wikipedia.org/wiki/Oak_(wine)');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('spirits-oak-aging', 'de', 'Eichenfässer & Holzchemie', 'Amerikanische und französische Eichenfässer, die Lignin-Vanilline, Laktone und Farbe spenden.', 'Eichenfässer dienen als mikroporöse Reifungsgefäße für Spirituosen und Weine. Das Ausbrennen (Toasten) karamellisiert Holzzucker und schafft eine Kohleschicht, die Schärfe filtert. Eichenholz gibt Vanillin, Kokosnuss-Laktone und Holztannine ab, die Destillate von [[spirits-islay|Islay Whiskys]] bis zu [[wine-bordeaux|Bordeaux-Weinen]] strukturieren.', 'https://de.wikipedia.org/wiki/Eichenfass');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('tea-terroir-processing', 'en', 'Tea: From Leaf to Infusion', 'How harvesting, withering, oxidation, and steaming shape white, green, oolong, and black teas.', 'All authentic teas originate from the leaves of [[tea-camellia|Camellia sinensis]]. The difference between green, oolong, and black tea lies in the degree of enzymatic oxidation. In [[tea-shizuoka|Shizuoka, Japan]], freshly picked leaves are quickly steamed to preserve chlorophyll and savory L-theanine amino acids.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('tea-terroir-processing', 'de', 'Tee: Vom Blatt zum Aufguss', 'Wie Ernte, Welken, Oxidation und Dämpfen die Vielfalt von grünem, weißem, Oolong- und schwarzem Tee formen.', 'Jeder echte Tee stammt von den Blättern der [[tea-camellia|Camellia sinensis]]. Der Unterschied zwischen grünem, Oolong- und schwarzem Tee liegt im Grad der enzymatischen Oxidation. In [[tea-shizuoka|Shizuoka, Japan]] werden frisch gepflückte Blätter rasch gedämpft, um Chlorophyll und herzhafte L-Theanin-Aminosäuren zu bewahren.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('tea-shizuoka', 'en', 'Shizuoka Prefecture', 'Japan''s premier tea capital beneath Mount Fuji, renowned for deep-steamed Fukamushi Sencha.', 'Shizuoka produces over 40% of Japan''s green tea. Blessed with volcanic soils, pure alpine meltwater, and coastal fog, tea masters cultivate [[tea-camellia|Camellia sinensis]] bushes that yield deep emerald, umami-rich green teas with a velvety sweet finish.', 'https://en.wikipedia.org/wiki/Shizuoka_Prefecture');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('tea-shizuoka', 'de', 'Präfektur Shizuoka', 'Japans führende Teeregion am Fuße des Mount Fuji, berühmt für tiefgedämpften Fukamushi Sencha.', 'Shizuoka erzeugt über 40 % des japanischen Grüntees. Begünstigt durch Vulkanböden, reines Gebirgswasser und Küstennebel, kultivieren Teemeister [[tea-camellia|Camellia sinensis]]-Sträucher, die tief smaragdgrüne, umamireiche Tees mit samtig-süßem Abgang hervorbringen.', 'https://de.wikipedia.org/wiki/Pr%C3%A4fektur_Shizuoka');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('tea-camellia', 'en', 'Camellia Sinensis', 'The evergreen tea plant rich in polyphenols, catechins, and relaxing L-theanine amino acids.', 'Camellia sinensis is an evergreen shrub native to East Asia. Varietal sinensis thrives in cool high terroirs like [[tea-shizuoka|Shizuoka]], producing delicate green teas, while varietal assamica yields robust, malty black teas. Catechins provide antioxidant bitterness, while L-theanine promotes calm mental clarity.', 'https://en.wikipedia.org/wiki/Camellia_sinensis');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('tea-camellia', 'de', 'Camellia Sinensis', 'Die Teepflanze, reich an Polyphenolen, Catechinen und beruhigenden L-Theanin-Aminosäuren.', 'Camellia sinensis ist ein immergrüner Teestrauch aus Ostasien. Die Varietät sinensis gedeiht in kühlen Hochlagen wie [[tea-shizuoka|Shizuoka]] und liefert feine Grüntees, während var. assamica kräftige Schwarztees ergibt. Catechine spenden gesunde Bitterkeit, während L-Theanin für entspannte geistige Klarheit sorgt.', 'https://de.wikipedia.org/wiki/Tee_(Pflanze)');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('cocktail-mixology-principles', 'en', 'Cocktails: The Art of Balance', 'Balancing strong, sweet, sour, bitter, and dilution in classic and modern craft cocktails.', 'Cocktail mixology is built on golden ratios harmonizing base spirits, citrus acids, sugar syrups, and aromatic modifiers like [[cocktail-aromatic-bitters|Aromatic Bitters]]. Shaking with ice introduces micro-bubbles and dilution for citrus sours, while stirring creates silky clarity for spirit-forward drinks aged in [[spirits-oak-aging|oak barrels]].', 'https://en.wikipedia.org/wiki/Cocktail');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('cocktail-mixology-principles', 'de', 'Cocktails: Die Kunst der Balance', 'Harmonie aus Basisspirituose, Süße, Säure, Bittere und Schmelzwasser in der Barkunst.', 'Moderne Mixology basiert auf ausgewogenen Verhältnissen von Basisspirituosen, Zitrussäuren, Zuckersirupen und Aromagebern wie [[cocktail-aromatic-bitters|Aromatic Bitters]]. Das Schütteln mit Eis sorgt für feine Belüftung und Kälte bei Sours, während Rühren seidige Klarheit für fassgelagerte Drinks aus [[spirits-oak-aging|Eichenfässern]] bewahrt.', 'https://de.wikipedia.org/wiki/Cocktail');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('cocktail-aromatic-bitters', 'en', 'Aromatic Bitters & Botanicals', 'Concentrated infusions of roots, bark, herbs, and spices that act as the spice rack of cocktails.', 'Bitters are high-proof alcoholic tinctures infused with gentian root, cinchona bark, clove, and cardamom. Even a few dashes bind discordant flavors together in cocktails such as the Old Fashioned and Manhattan, complementing base [[spirits-distillation-craft|distilled spirits]].', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('cocktail-aromatic-bitters', 'de', 'Aromatic Bitters & Botanicals', 'Konzentrierte Auszüge aus Wurzeln, Rinden und Kräutern, die als Gewürzregal der Bar fungieren.', 'Bitters sind hochprozentige Essenzen auf Basis von Enzianwurzel, Chinarinde, Gewürznelken und Kardamom. Bereits wenige Spritzer (Dashes) verbinden gegensätzliche Aromen im Old Fashioned oder Manhattan und harmonieren ideal mit [[spirits-distillation-craft|destillierten Spirituosen]].', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('soda-effervescence-botanicals', 'en', 'Tonics & Craft Sodas: Bubbles & Botanicals', 'The role of carbonation, natural cane sugars, and medicinal cinchona bark in refreshing mixers.', 'Modern premium mixers use natural carbonation and botanical infusions. High-quality tonic water derives its characteristic crisp bitterness from [[soda-quinine|Quinine]], historically harvested from the South American fever tree. Pairings with craft [[spirits-distillation-craft|spirits]] rely on fine perlage to carry aroma to the palate.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('soda-effervescence-botanicals', 'de', 'Tonics & Craft-Sodas: Perlung & Botanicals', 'Die Rolle von feinster Kohlensäure, Rohrzucker und heilsamer Chinarinde in erstklassigen Mixern.', 'Hochwertige Filler und Craft-Sodas setzen auf feinperlige Kohlensäure und natürliche Pflanzenextrakte. Premium Tonic Water verdankt seine frische Bitterkeit dem [[soda-quinine|Chinin]], das traditionell aus der Rinde des Fieberbaums stammt. In Kombination mit [[spirits-distillation-craft|Spirituosen]] transportiert die Perlage Aromen optimal an den Gaumen.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('soda-quinine', 'en', 'Quinine (Cinchona Bark)', 'The bitter crystalline alkaloid from the Cinchona tree that gives tonic water its signature snap.', 'Extracted from the bark of the Andean Cinchona tree, quinine was originally consumed by British colonial soldiers in India to prevent malaria. When blended with soda water and sugar, it gave birth to Indian Tonic Water. It provides a sharp, appetite-stimulating bitterness that balances botanical [[cocktail-mixology-principles|cocktails]].', 'https://en.wikipedia.org/wiki/Tonic_water');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('soda-quinine', 'de', 'Chinin (Chinarinde)', 'Das bittere Alkaloid aus dem Chinarindenbaum, das Tonic Water seinen charakteristischen Biss verleiht.', 'Gewonnen aus der Rinde des südamerikanischen Chinarindenbaums, wurde Chinin ursprünglich als Malariaschutz genutzt. Gemischt mit Sodawasser und Zucker entstand das klassische Indian Tonic Water. Die herbe Bittere regt den Gaumen an und balanciert kräuterbetonte [[cocktail-mixology-principles|Cocktails]] aus.', 'https://de.wikipedia.org/wiki/Tonic_Water');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-wild-fermentations', 'en', 'Ancient Ferments: Mead, Cider & Kombucha', 'Wild honey ferments, tannic apple ciders, and SCOBY cultures that predate modern industrial brewing.', 'Beyond grain and grape, humanity has cultivated diverse wild ferments for millennia. Honey ferments into mead, while vintage apples in [[other-normandy|Normandy]] yield complex dry ciders. Probiotic cultures like kombucha rely on symbiotic yeasts and bacteria fermenting [[tea-camellia|Camellia sinensis]] tea.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-wild-fermentations', 'de', 'Uralte Fermente: Met, Cider & Kombucha', 'Wilde Honiggärung, gerbstoffreiche Apfel-Cidres und SCOBY-Kulturen mit jahrtausendealter Tradition.', 'Abseits von Getreide und Trauben kultiviert die Menschheit seit Jahrtausenden wilde Fermentationsgetränke. Honig vergärt zu Met, während traditionsreiche Streuobstsorten in der [[other-normandy|Normandie]] komplexe, trockene Cidres ergeben. Kombucha entsteht durch symbiotische Hefen und Bakterien, die [[tea-camellia|Camellia sinensis]]-Tee verstoffwechseln.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-normandy', 'en', 'Normandy (Normandie)', 'The maritime orchard region of northern France celebrated for traditional Cidre Bouché and Calvados.', 'With over 700 heritage apple cultivars, Normandy''s temperate damp climate creates bittersweet, tannin-packed ciders. Natural fermentation and aging in [[spirits-oak-aging|oak barrels]] produce rustic, farmyard complexity and effervescent refreshment.', 'https://en.wikipedia.org/wiki/Cider');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-normandy', 'de', 'Normandie', 'Die nordfranzösische Obstgartenregion, berühmt für traditionellen Cidre Bouché und Calvados.', 'Mit über 700 traditionellen Apfelsorten und feuchtem Atlantikklima bringt die Normandie herbe, tanninreiche Cidres hervor. Spontangärung und die Reife in [[spirits-oak-aging|Eichenfässern]] verleihen dem Cidre und Calvados eine facettenreiche Frische und feine Würze.', 'https://de.wikipedia.org/wiki/Cidre');
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-white-wine-acidity-and-texture', 'en', 'White Wine: Acidity and Texture', 'An overview of the production choices, sensory characteristics, and serving context that define this subject.', 'White Wine: Acidity and Texture is best understood by examining ingredients, production technique, sensory balance, and serving conditions. An overview of the production choices, sensory characteristics, and serving context that define this subject. When tasting examples, assess aroma, sweetness, acidity or bitterness, body, texture, and finish; these traits vary with producer and style.', NULL);
