INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('wine-chardonnay', 'de', 'Chardonnay', 'Ein wichtiger Rohstoff, dessen Herkunft, Zusammensetzung und Verarbeitung Geschmack, Textur und Herstellung beeinflussen.', 'Chardonnay beeinflusst die Herstellung und den sensorischen Charakter von Getränken. An important raw material whose origin, composition, and handling influence beverage flavor, texture, and production. Die Wirkung hängt von Herkunft, Sorte, Verarbeitung, Dosierung und dem Zusammenspiel mit anderen Zutaten ab. Das Verständnis der Zutat erklärt Aroma, Textur, Balance und Beständigkeit des fertigen Getränks.', NULL);
