INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-kombucha-fermentation-and-balance', 'en', 'Kombucha: Fermentation and Balance', 'An overview of the production choices, sensory characteristics, and serving context that define this subject.', 'Kombucha: Fermentation and Balance is best understood by examining ingredients, production technique, sensory balance, and serving conditions. An overview of the production choices, sensory characteristics, and serving context that define this subject. When tasting examples, assess aroma, sweetness, acidity or bitterness, body, texture, and finish; these traits vary with producer and style.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-kombucha-fermentation-and-balance', 'de', 'Kombucha: Fermentation and Balance', 'Überblick über Herstellung, sensorische Eigenschaften und Servierweise dieses Themas.', 'Kombucha: Fermentation and Balance: Im Mittelpunkt stehen Zutaten, Herstellungstechnik, sensorische Balance und Servierbedingungen. An overview of the production choices, sensory characteristics, and serving context that define this subject. Bei der Verkostung sind Duft, Süße, Säure oder Bitterkeit, Körper, Textur und Nachhall zu beurteilen; diese Merkmale variieren je nach Erzeuger und Stil.', NULL);
