INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-somerset', 'en', 'Somerset', 'A beverage region or cultural center shaped by local climate, raw materials, history, and production traditions.', 'Somerset has a distinctive place in beverage culture. A beverage region or cultural center shaped by local climate, raw materials, history, and production traditions. Geography and climate can influence available raw materials and production choices, while local history and expertise shape regional traditions. Individual producers differ, so regional descriptors should be treated as tendencies rather than guarantees.', NULL);
INSERT INTO encyclopedia_article_translations (article_id, language_code, title, summary, content, wikipedia_url) VALUES ('other-somerset', 'de', 'Somerset', 'Getränkeregion oder kulturelles Zentrum, geprägt von Klima, Rohstoffen, Geschichte und Herstellungstraditionen.', 'Somerset nimmt einen besonderen Platz in der Getränkekultur ein. A beverage region or cultural center shaped by local climate, raw materials, history, and production traditions. Geografie und Klima beeinflussen Rohstoffe und Herstellungsverfahren; Geschichte und Fachwissen prägen regionale Traditionen. Einzelne Erzeuger unterscheiden sich, daher sind regionale Beschreibungen als Tendenzen und nicht als Garantien zu verstehen.', NULL);
